function Say($text, $color = "White") { Write-Host $text -ForegroundColor $color }

# ---------- 1. Project folder dhundho ----------
$Root = $PSScriptRoot
if (-not $Root) { $Root = (Get-Location).Path }

if (-not (Test-Path (Join-Path $Root "package.json"))) {
    $here = (Get-Location).Path
    if (Test-Path (Join-Path $here "package.json")) {
        $Root = $here
    } else {
        Say ""
        Say "GALTI: package.json nahi mila." Red
        Say "Is script ko apne 'crm' project folder (jisme package.json hai) me rakh kar chalayein." Yellow
        exit 1
    }
}

if (Test-Path (Join-Path $Root "src\app")) {
    $AppDir = Join-Path $Root "src\app"
} elseif (Test-Path (Join-Path $Root "app")) {
    $AppDir = Join-Path $Root "app"
} else {
    Say "GALTI: 'app' ya 'src\app' folder nahi mila. Kya yeh Next.js project hai?" Red
    exit 1
}


$Stamp = Get-Date -Format "yyyy-MM-dd_HH-mm-ss"
$BackupDir = Join-Path $Root ("_backups\" + $Stamp)
$Utf8NoBom = New-Object System.Text.UTF8Encoding($false)
$Updated = @()
$Created = @()
$Skipped = @()

Say ""
Say "Project folder : $Root" Cyan
Say "App folder     : $AppDir" Cyan
Say ""

# ---------- 2. Helper: backup + write ----------
function Write-ProjectFile([string]$Target, [string]$Base64) {
    # [System.IO] use karte hain taaki [phone] / [slug] jaise folder naam theek se chalein
    $bytes = [Convert]::FromBase64String($Base64)
    $rel = $Target.Substring($Root.Length).TrimStart("\")

    if ([System.IO.File]::Exists($Target)) {
        $backupPath = Join-Path $BackupDir $rel
        [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($backupPath))
        [System.IO.File]::Copy($Target, $backupPath, $true)
        $script:Updated += $rel
        Say "  UPDATE  $rel" Green
    } else {
        $script:Created += $rel
        Say "  NEW     $rel" Yellow
    }

    [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($Target))
    [System.IO.File]::WriteAllBytes($Target, $bytes)
}

# Sirf asli code folders me dhundho: app\ aur components\
# (backup / disabled / temp folders ko kabhi nahi chhedte)
function Find-ProjectFiles([string]$Name) {
    $searchRoots = @($AppDir)
    foreach ($c in @((Join-Path $Root "components"), (Join-Path $Root "src\components"))) {
        if ((Test-Path $c) -and ($searchRoots -notcontains $c)) { $searchRoots += $c }
    }
    $skipPattern = '\\(node_modules|\.next|_backups|\.git)\\|(?i)backup|disabled|[-_]temp|rider-step2-6-fix|live-source'
    $results = @()
    foreach ($r in $searchRoots) {
        $results += Get-ChildItem -LiteralPath $r -Recurse -File -Filter $Name -ErrorAction SilentlyContinue |
            Where-Object { $_.FullName.Substring($Root.Length) -notmatch $skipPattern }
    }
    return $results
}

# ---------- 3. API routes (fixed jagah) ----------
Say "API files:" White
Write-ProjectFile (Join-Path $AppDir "api\processing\orders\route.ts") ($B64_PROCESSING_ROUTE -join "")
Write-ProjectFile (Join-Path $AppDir "api\rider-my-tasks\route.ts")    ($B64_RIDER_TASKS -join "")
Write-ProjectFile (Join-Path $AppDir "api\rider-dashboard\route.ts")   ($B64_RIDER_DASH -join "")

